import sys, ezdxf
d = r'C:\Users\DELL\Desktop\AI_CAD\AI_Work\Thang-11\25-11-2026\521125-01\Sua_loi'
code = sys.argv[1]
def dump(p):
    doc = ezdxf.readfile(p)
    out = []
    for e in doc.modelspace():
        t = e.dxftype()
        ly = e.dxf.layer
        col = e.dxf.color if e.dxf.hasattr('color') else None
        if t == 'LINE':
            s = (round(e.dxf.start.x, 2), round(e.dxf.start.y, 2)); en = (round(e.dxf.end.x, 2), round(e.dxf.end.y, 2))
            out.append((ly, col, 'L', min(s, en), max(s, en)))
        elif t == 'CIRCLE':
            out.append((ly, col, 'C', (round(e.dxf.center.x, 2), round(e.dxf.center.y, 2)), round(e.dxf.radius, 2)))
        elif t == 'ARC':
            out.append((ly, col, 'A', (round(e.dxf.center.x, 2), round(e.dxf.center.y, 2)), round(e.dxf.radius, 2), round(e.dxf.start_angle), round(e.dxf.end_angle)))
        else:
            out.append((ly, col, t, str(e.dxf.all_existing_dxf_attribs())[:80]))
    return out
T = dump(d + '\\' + code + 'T.dxf'); F = dump(d + '\\' + code + 'F.dxf')
sT = set(map(str, T)); sF = set(map(str, F))
print('layers T', sorted({x[0] for x in T}), 'F', sorted({x[0] for x in F}))
print('--- only T')
for x in sorted(T, key=str):
    if str(x) not in sF: print(x)
print('--- only F')
for x in sorted(F, key=str):
    if str(x) not in sT: print(x)

